class Solution {
  public int countCoveredBuildings(int n, int[][] buildings) {
    int[] rowMin = new int[n + 1],
        rowMax = new int[n + 1],
        colMin = new int[n + 1],
        colMax = new int[n + 1];
    Arrays.fill(rowMin, Integer.MAX_VALUE);
    Arrays.fill(colMin, Integer.MAX_VALUE);
    for (int[] b : buildings) {
      int x = b[0], y = b[1];
      rowMin[x] = Math.min(rowMin[x], y);
      rowMax[x] = Math.max(rowMax[x], y);
      colMin[y] = Math.min(colMin[y], x);
      colMax[y] = Math.max(colMax[y], x);
    }
    int covered = 0;
    for (int[] b : buildings) {
      int x = b[0], y = b[1];
      if (rowMin[x] < y && y < rowMax[x] && colMin[y] < x && x < colMax[y]) covered++;
    }
    return covered;
  }
}
